            rts
; End of subroutine: sys.stack_size


; ---- Subroutine: sys.cpuAtLeast68020 ----
    ALIGN 2

sys.cpuAtLeast68020:
            move.l  4.w,a6
            move.w  296(a6),d0
            andi.w  #$008e,d0
            seq     d0
            tst.b   d0
