p8b_txt:

; ---- Subroutine: p8b_txt.p8s_chrout ----
    ALIGN 2

p8b_txt.p8s_chrout:
            move.l  sys.DOSBase,a6
            move.b  d0,-(sp)          ; 1. Push character onto the stack. A7 now points to it!
            move.l  4.w,a0
            cmp.w   #36,20(a0)      ; KS 2.0 = V36
            bcc.s   .use_writechars

            jsr     -60(a6)           ; Output()
            move.l  d0, d1
            move.l  sp, d2             ; D2 = Pointer to our character (Current Stack Pointer)
            moveq   #1, d3             ; D3 = We only want to write exactly 1 byte
            jsr     -48(a6)           ; Write()
            addq.l  #2, sp
            rts

.use_writechars:
            move.l  sp, d1
            moveq   #1, d2
            jsr     -942(a6)        ; WriteChars (ks 2.0+)
            addq.l  #2, sp
            rts
; End of subroutine: p8b_txt.p8s_chrout


; ---- Subroutine: p8b_txt.p8s_flush ----
    ALIGN 2

p8b_txt.p8s_flush:
            move.l  4.w,a6
            cmp.w   #36,20(a6)      ; KS 2.0 = V36
            bcc.s   .do_flush
            rts
.do_flush:
            move.l  sys.DOSBase,a6
            jsr     -60(a6)
            move.l  d0,d1
            jmp     -360(a6)       ; Flush (ks 2.0+)
; End of subroutine: p8b_txt.p8s_flush


; ---- Subroutine: p8b_txt.p8s_print ----
    ALIGN 2

p8b_txt.p8s_print:
            move.l  4.w,a6
            cmp.w   #36,20(a6)      ; KS 2.0 = V36
            bcc.s   .use_putstr
            move.l  a0,d2
            jsr  strings.length
            move.l  d0,d3
            move.l  sys.DOSBase,a6
            jsr     -60(a6)           ; Output()
            move.l  d0,d1
            jmp     -48(a6)           ; Write()
.use_putstr:
            move.l  sys.DOSBase,a6
            move.l  a0,d1
            jsr     -948(a6)          ; PutStr()  (KS 2.0+)
            jsr     -60(a6)         ; Output()
            move.l  d0,d1
            jmp     -360(a6)       ; Flush (ks 2.0+)
; End of subroutine: p8b_txt.p8s_print


; ---- Subroutine: p8b_txt.p8s_vprintf ----
    ALIGN 2

p8b_txt.p8s_vprintf:
            move.l  4.w,a6
            cmp.w   #36,20(a6)      ; KS 2.0 = V36
            bcs.s   .no_ks20
            move.l  sys.DOSBase,a6
            jmp  dos.VPrintf(a6)

.no_ks20:
            jmp  p8b_txt.p8s_no_ks20_alert
; End of subroutine: p8b_txt.p8s_vprintf


; ---- Subroutine: p8b_txt.p8s_no_ks20_alert ----
    ALIGN 2

p8b_txt.p8s_no_ks20_alert:
            move.l  #$00070001,d0
            lea     _msg(pc),a0
            moveq   #40,d1
            move.l  sys.IntuitionBase,a6
            jsr     -90(a6)                 ; DisplayAlert
            moveq   #1,d0
            jmp     sys.exit

            even
_msg:
            dc.w    20
            dc.b    16
            dc.b    "textio/conv number format routines require Kickstart 2.0+",0
            dc.b    0
            ; !notreached!
; End of subroutine: p8b_txt.p8s_no_ks20_alert


; Block: p8b_conv

p8b_conv:

; ---- Subroutine: p8b_conv.p8s_putcharproc ----
    ALIGN 2

p8b_conv.p8s_putcharproc:
            move.b  d0, (a3)+           ; Store character in buffer and advance pointer
            rts                         ; Return control to RawDoFmt loop
; End of subroutine: p8b_conv.p8s_putcharproc


; Block: strings

strings:

; ---- Subroutine: strings.length ----
    ALIGN 2

strings.length:
            moveq    #0,d0
            bra.s    .enter
.loop:
            addq.w   #1,d0
.enter:
            tst.b    (a0)+
            bne      .loop
            rts
; End of subroutine: strings.length


; ---- Subroutine: strings.compare ----
    ALIGN 2

strings.compare:
            jmp  prog8_lib.strcmp
; End of subroutine: strings.compare


; ---- Subroutine: strings.hash ----
    ALIGN 2

strings.hash:
            movea.l  d0,a0
            move.b   #179,d0
            moveq    #0,d1
            move.w   d1,ccr          ; clear flags (X=0 for roxl)
            bra      .enter
.loop:
            roxl.b   #1,d0
            eor.b    d1,d0
.enter:
            move.b   (a0)+,d1
            bne      .loop
            rts
; End of subroutine: strings.hash


; ---- Subroutine: strings.copy ----
    ALIGN 2

strings.copy:
            movea.l  d0,a0
            movea.l  d1,a1
            moveq    #0,d0
.loop:
            move.b   (a0)+,d2
            move.b   d2,(a1)+
            beq      .done
            addq.l   #1,d0
            bra.s    .loop
.done:
            rts
; End of subroutine: strings.copy


; ---- Subroutine: strings.ncopy ----
    ALIGN 2

strings.ncopy:
            movea.l  d0,a0
            movea.l  d1,a1
            moveq    #0,d0
            tst.b    d2
            beq      .zero
.loop:
            move.b   (a0)+,d1
            move.b   d1,(a1)+
            beq      .done
            addq.l   #1,d0
            subq.b   #1,d2
            bne      .loop
            ; maxlength bytes reached - null-terminate
            clr.b    (a1)
            rts
.zero:
            clr.b    (a1)
.done:
            rts
; End of subroutine: strings.ncopy


; Block: prog8_math

prog8_math:
; 68000 math routines that should always be included by the compiler

  SECTION .bss,bss

math._sqrt_l.value:    ds.l 1
math._sqrt_uw.value:   ds.w 1
math._sqrt_ub.value:   ds.b 1

  SECTION .text,code  ; back to code section


math._sqrt_ub:
    moveq  #0,d1
    clr.l  d0
    move.b  math._sqrt_ub.value,d0
    beq  .done_ub
    moveq  #4,d2
.loop_ub:
    move.l  d1,d3
    bset  d2,d3
    mulu.w  d3,d3
    cmp.w  d0,d3
    bhi  .skip_ub
    bset  d2,d1
.skip_ub:
    subq  #1,d2
    bpl  .loop_ub
.done_ub:
    move.b  d1,d0
    rts

math._sqrt_uw:
    moveq  #0,d1
    move.w  math._sqrt_uw.value,d0
    beq  .done_uw
    moveq  #8,d2
.loop_uw:
    move.l  d1,d3
    bset  d2,d3
    mulu.w  d3,d3
    cmp.l  d0,d3
    bhi  .skip_uw
    bset  d2,d1
.skip_uw:
    subq  #1,d2
    bpl  .loop_uw
.done_uw:
    move.b  d1,d0
    rts

math._sqrt_l:
    moveq  #0,d1
    move.l  math._sqrt_l.value,d0
    beq  .done_l
    moveq  #15,d2
.loop_l:
    move.l  d1,d3
    bset  d2,d3
    mulu.w  d3,d3
    cmp.l  d0,d3
    bhi  .skip_l
    bset  d2,d1
.skip_l:
    subq  #1,d2
    bpl  .loop_l
.done_l:
    move.w  d1,d0
    rts
; 68000 (amiga500) 32-bit multiplication / division / modulo
;
; The plain 68000 only has 8x8 and 16x16 multiply/divide instructions, so the
; 32-bit operations have to be built up from those. The routines below are
; written to integrate directly with the code generator: they take their
; arguments in registers (d0/d1) and return their results in registers, and the
; division/modulo share a single long-division core that produces both quotient
; and remainder at once.
;
; The p8_*32 wrapper routines use the amiga utility.library for a fast path on
; Kickstart 2.0+ (when sys.UtilityBase is non-zero), with a software fallback
; for Kickstart 1.3 (where utility.library is not available).

  SECTION .text,code

; d0 = d0 * d1  (signed or unsigned, keeping the low 32 bits)
; Uses four 16-bit partial products:  result = x0*y0 + (x0*y1 + x1*y0)<<16  (+ x1*y1<<32, dropped).
p8_mulsi3:
    move.w  d0,d2          ; d2 = x0 (low half of x)
    mulu.w  d1,d2          ; d2 = x0*y0
    move.l  d0,d3
    lsr.l   #8,d3
    lsr.l   #8,d3          ; d3 = x1 (high half of x)
    mulu.w  d1,d3          ; d3 = x1*y0
    swap    d1             ; d1 = y1 (high half of y)
    mulu.w  d0,d1          ; d1 = x0*y1
    add.l   d3,d1          ; d1 = x0*y1 + x1*y0  (the two cross terms)
    swap    d1
    clr.w   d1             ; d1 = (cross terms) << 16
    add.l   d1,d2          ; d2 = x0*y0 + cross<<16
    move.l  d2,d0
    rts

; Unsigned 32/32 -> 32: d0 = dividend, d1 = divisor  ->  d0 = quotient, d1 = remainder.
; Plain shift-and-subtract long division, 32 iterations, no 32-bit divide needed.
p8_udivmod32_sw:
    move.l  d1,d2          ; d2 = divisor
    beq.s   .divz          ; divide by zero: quotient 0, remainder = dividend
    moveq   #31,d3         ; 32 bit positions to process
    move.l  d0,d4          ; d4 = dividend (shifted through to feed the bits)
    clr.l   d0             ; d0 = quotient (built up)
    clr.l   d5             ; d5 = remainder (built up)
.loop:
    lsl.l   #1,d4          ; shift the next dividend bit out into the X flag
    roxl.l  #1,d5          ; remainder = (remainder<<1) | that dividend bit
    lsl.l   #1,d0          ; quotient <<= 1
    cmp.l   d2,d5
    blo.s   .next
    sub.l   d2,d5          ; remainder -= divisor
    addq.l  #1,d0          ; quotient |= 1
.next:
    dbf     d3,.loop
    move.l  d5,d1          ; remainder
    rts
.divz:
    move.l  d0,d1          ; remainder = dividend
    clr.l   d0             ; quotient = 0
    rts

; Signed 32/32 -> 32: d0 = dividend, d1 = divisor  ->  d0 = quotient, d1 = remainder.
; Computed with absolute values, then the signs are corrected: the quotient takes
; the sign of (dividend xor divisor), the remainder takes the sign of the dividend
; (truncating division, like C).
p8_sdivmod32_sw:
    move.l  d0,d6          ; d6 = dividend (keep original for sign)
    move.l  d1,d7
    eor.l   d6,d7          ; d7 bit31 set if the two signs differ
    tst.l   d0
    bpl.s   .nabs
    neg.l   d0             ; d0 = |dividend|
.nabs:
    tst.l   d1
    bpl.s   .dabs
    neg.l   d1             ; d1 = |divisor|
.dabs:
    jsr     p8_udivmod32_sw  ; d0 = |quotient|, d1 = |remainder|
    tst.l   d7
    bpl.s   .qpos
    neg.l   d0             ; flip quotient sign if signs differed
.qpos:
    tst.l   d6
    bpl.s   .rpos
    neg.l   d1             ; flip remainder sign to match dividend
.rpos:
    rts

; Wrappers. d0/d1 in, d0 (and d1 for divmod) out. When sys.UtilityBase is non-zero
; (Kickstart 2.0+) the amiga utility.library is used for a fast result; otherwise the
; software routines above are used.

; d0*d1 (signed) -> d0
p8_smult32:
    move.l  sys.UtilityBase,d2   ; scratch (d0=arg1, d1=arg2 preserved)
    beq.w   p8_mulsi3
    move.l  d2,a6
    jmp     -138(a6)      ; utility.library SMult32

; d0/d1 (signed) -> d0=quotient, d1=remainder
p8_sdivmod32:
    move.l  sys.UtilityBase,d2   ; scratch (d0=dividend, d1=divisor preserved)
    beq.w   p8_sdivmod32_sw
    move.l  d2,a6
    jmp     -150(a6)      ; utility.library SDivMod32

; Block: prog8_lib

prog8_lib:

; ---- Subroutine: prog8_lib.strcmp ----
    ALIGN 2

prog8_lib.strcmp:
            movea.l  d0,a0
            movea.l  d1,a1
.loop:
            move.b   (a0)+,d0
            move.b   (a1)+,d1
            cmp.b    d1,d0
            bne      .diff
            tst.b    d0
            bne      .loop
            moveq    #0,d0
            rts
.diff:
            blo      .less
            moveq    #1,d0
            rts
.less:
            moveq    #-1,d0
            rts
; End of subroutine: prog8_lib.strcmp


